{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    mins = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    imps = [seg['importance'] for seg in segments]
    total_min = sum(mins)
    total_cap = sum(caps)
    if budget < total_min or budget > total_cap:
        raise ValueError('Invalid budget')
    alloc = mins[:]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if alloc[i] < caps[i]:
                ratio = imps[i] / (alloc[i] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {}
    for seg, a in zip(segments, alloc):
        by_name[seg['name']] = a
    total = sum(alloc)
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
